import{q as r}from"./Clw5_Vka.js";const n="vt_applications",l=()=>{const i=localStorage.getItem(n);if(!i)return[];try{return JSON.parse(i)}catch{return[]}},t=r(l());function u(){return{applications:t,saveApplication:e=>{const a=t.value.findIndex(o=>o.id===e.id);a>=0?t.value[a]=e:t.value.unshift(e),localStorage.setItem(n,JSON.stringify(t.value))},deleteApplication:e=>{t.value=t.value.filter(a=>a.id!==e),localStorage.setItem(n,JSON.stringify(t.value))},generateAppId:()=>"app-"+Date.now()+"-"+Math.random().toString(36).slice(2,7)}}export{u};
